CREATE TABLE training_review(id uuid PRIMARY KEY, training_session_id uuid UNIQUE NOT NULL REFERENCES training_session, practitioner_profile_id uuid NOT NULL REFERENCES practitioner_profile, organization_id uuid NOT NULL REFERENCES organization, martial_art_id uuid NOT NULL REFERENCES martial_art, status varchar(20) NOT NULL CHECK(status IN ('PENDING','REVIEWED')), created_at timestamptz NOT NULL, reviewed_at timestamptz, version bigint NOT NULL DEFAULT 0);
CREATE INDEX pending_review ON training_review(organization_id,status,created_at,id);
CREATE TABLE feedback(id uuid PRIMARY KEY, review_id uuid UNIQUE NOT NULL REFERENCES training_review, training_session_id uuid NOT NULL REFERENCES training_session, practitioner_profile_id uuid NOT NULL REFERENCES practitioner_profile, author_user_id uuid NOT NULL REFERENCES app_user, organization_id uuid NOT NULL REFERENCES organization, body varchar(4000) NOT NULL CHECK(length(trim(body))>0), created_at timestamptz NOT NULL);
CREATE INDEX feedback_athlete ON feedback(practitioner_profile_id,created_at DESC,id);
CREATE TABLE goal(id uuid PRIMARY KEY, practitioner_profile_id uuid NOT NULL REFERENCES practitioner_profile, organization_id uuid NOT NULL REFERENCES organization, martial_art_id uuid NOT NULL REFERENCES martial_art, assigned_by_user_id uuid NOT NULL REFERENCES app_user, source_training_session_id uuid REFERENCES training_session, related_technique_id uuid REFERENCES technique, title varchar(160) NOT NULL, objective varchar(2000) NOT NULL, coach_observation varchar(2000), priority varchar(20) NOT NULL CHECK(priority IN ('LOW','NORMAL','HIGH')), review_date date, status varchar(20) NOT NULL CHECK(status IN ('ACTIVE','ACHIEVED','CANCELLED')), source varchar(20) NOT NULL DEFAULT 'ORGANIZATION' CHECK(source IN ('PERSONAL','ORGANIZATION','OFFICIAL')), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 0);
CREATE INDEX goal_athlete ON goal(practitioner_profile_id,status,created_at DESC,id);
CREATE INDEX goal_organization ON goal(organization_id);
